#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    cin >> n;
    vector<long long> nxt(n);
    for (int i = 0; i < n; i++) cin >> nxt[i];

    vector<int> walk(n + 1, 0);
    vector<long long> step(n + 1, 0);
    long long best = -1;
    for (int start = 1; start <= n; start++) {
        if (walk[start]) continue;
        int v = start;
        long long t = 0;
        while (v != 0 && !walk[v]) {
            walk[v] = start;
            step[v] = t;
            t++;
            v = (int)nxt[v - 1];
        }
        if (v != 0 && walk[v] == start) best = max(best, t - step[v]);
    }
    cout << best << "\n";

    return 0;
}

