import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long[] nxt = new long[(int) n];
        for (int i = 0; i < nxt.length; i++) nxt[i] = Long.parseLong(next());

        int nodes = (int) n;
        int[] walk = new int[nodes + 1];
        long[] step = new long[nodes + 1];
        long best = -1;
        for (int start = 1; start <= nodes; start++) {
            if (walk[start] != 0) continue;
            int v = start;
            long t = 0;
            while (v != 0 && walk[v] == 0) {
                walk[v] = start;
                step[v] = t;
                t++;
                v = (int) nxt[v - 1];
            }
            if (v != 0 && walk[v] == start) best = Math.max(best, t - step[v]);
        }
        System.out.println(best);
    }
}
